import "server-only";

import {
  DeleteObjectCommand,
  GetObjectCommand,
  ListObjectsV2Command,
  PutObjectCommand,
  S3Client,
  S3ServiceException,
} from "@aws-sdk/client-s3";
import { recordIncident } from "@/lib/incidents";
import { isValidResumeKey } from "@/lib/resumes";

/**
 * Resume files live in one private Cloudflare R2 bucket, reached through the S3 API.
 * Only this module talks to R2. Keys are generated by the app (see src/lib/resumes.ts);
 * every function here refuses a key that does not match the key rule.
 *
 * Env: R2_ACCOUNT_ID, R2_ACCESS_KEY_ID, R2_SECRET_ACCESS_KEY, R2_BUCKET.
 */

const REQUEST_TIMEOUT_MS = 20_000;

/** Thrown for any storage failure. Carries only the error name and HTTP status, never key material. */
export class StorageError extends Error {
  readonly status?: number;
  constructor(
    readonly operation: "put" | "get" | "delete" | "list" | "config",
    cause: unknown
  ) {
    const name = cause instanceof Error ? cause.name : "UnknownError";
    super(`Resume storage ${operation} failed: ${name}`);
    this.name = "StorageError";
    this.status = cause instanceof S3ServiceException ? cause.$metadata.httpStatusCode : undefined;
  }
}

function readConfig() {
  const accountId = process.env.R2_ACCOUNT_ID;
  const accessKeyId = process.env.R2_ACCESS_KEY_ID;
  const secretAccessKey = process.env.R2_SECRET_ACCESS_KEY;
  const bucket = process.env.R2_BUCKET;
  if (!accountId || !accessKeyId || !secretAccessKey || !bucket) return null;
  return { accountId, accessKeyId, secretAccessKey, bucket };
}

/** True when all four R2 variables are set. `npm run build` must work without them. */
export function storageConfigured(): boolean {
  return readConfig() !== null;
}

let client: S3Client | null = null;
let clientBucket = "";

function getClient(): { client: S3Client; bucket: string } {
  const config = readConfig();
  if (!config) throw new StorageError("config", new Error("StorageNotConfigured"));
  if (!client) {
    client = new S3Client({
      region: "auto",
      endpoint: `https://${config.accountId}.r2.cloudflarestorage.com`,
      credentials: { accessKeyId: config.accessKeyId, secretAccessKey: config.secretAccessKey },
      requestHandler: { requestTimeout: REQUEST_TIMEOUT_MS, throwOnRequestTimeout: true },
    });
    clientBucket = config.bucket;
  }
  return { client, bucket: clientBucket };
}

function assertKey(key: string) {
  if (!isValidResumeKey(key)) throw new StorageError("config", new Error("InvalidResumeKey"));
}

/** Uploads a resume. Overwrites nothing: keys are random and checked for clashes by the DB unique index. */
export async function putResume(key: string, bytes: Uint8Array, contentType: string): Promise<void> {
  assertKey(key);
  const { client, bucket } = getClient();
  try {
    await client.send(
      new PutObjectCommand({
        Bucket: bucket,
        Key: key,
        Body: bytes,
        ContentType: contentType,
        ContentLength: bytes.byteLength,
        ContentDisposition: "attachment",
      })
    );
  } catch (err) {
    throw new StorageError("put", err);
  }
}

export type ResumeStream = { stream: ReadableStream; contentLength?: number; contentType?: string };

/** Opens a resume for download. Throws StorageError("get") with status 404 when the object is missing. */
export async function openResumeStream(key: string): Promise<ResumeStream> {
  assertKey(key);
  const { client, bucket } = getClient();
  try {
    const out = await client.send(new GetObjectCommand({ Bucket: bucket, Key: key }));
    if (!out.Body) throw new Error("EmptyBody");
    return { stream: out.Body.transformToWebStream(), contentLength: out.ContentLength, contentType: out.ContentType };
  } catch (err) {
    throw new StorageError("get", err);
  }
}

/** Deletes a resume. Deleting a missing key is not an error in S3 or R2. */
export async function deleteResume(key: string): Promise<void> {
  assertKey(key);
  const { client, bucket } = getClient();
  try {
    await client.send(new DeleteObjectCommand({ Bucket: bucket, Key: key }));
  } catch (err) {
    throw new StorageError("delete", err);
  }
}

/**
 * Deletes a resume without throwing. A failure is recorded as an incident so the
 * daily cleanup job can remove the orphan later and the admin can see it happened.
 */
export async function deleteResumeQuietly(key: string, context?: Record<string, string | undefined>): Promise<void> {
  try {
    await deleteResume(key);
  } catch (err) {
    const e = err instanceof StorageError ? err : new StorageError("delete", err);
    console.error("[resume-storage] delete failed", key, e.message);
    // The key is a random name, not applicant data, so it is safe to record. It lets an
    // admin delete the file by hand from the bucket if the cleanup job is not running.
    await recordIncident("resume.delete", `A resume file could not be deleted from storage. File: ${key}`, {
      error: e.message,
      status: e.status,
      key,
      ...context,
    });
  }
}

export type ResumeObject = { key: string; size: number; lastModified?: Date };

/** Lists one page of resume objects for the cleanup job. */
export async function listResumeObjects(cursor?: string): Promise<{ objects: ResumeObject[]; nextCursor?: string }> {
  const { client, bucket } = getClient();
  try {
    const out = await client.send(
      new ListObjectsV2Command({ Bucket: bucket, Prefix: "resumes/", ContinuationToken: cursor, MaxKeys: 1000 })
    );
    const objects: ResumeObject[] = [];
    for (const item of out.Contents ?? []) {
      if (item.Key) objects.push({ key: item.Key, size: item.Size ?? 0, lastModified: item.LastModified });
    }
    return { objects, nextCursor: out.IsTruncated ? out.NextContinuationToken : undefined };
  } catch (err) {
    throw new StorageError("list", err);
  }
}
